import{_ as e,o,c as s,a2 as a}from"./chunks/framework.BfWdyVj4.js";const p=JSON.parse('{"title":"Goodnight","description":"","frontmatter":{},"headers":[],"relativePath":"features/goodnight.md","filePath":"features/goodnight.md","lastUpdated":1793096821000}'),i={name:"features/goodnight.md"};function n(h,t,d,r,l,u){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="goodnight" tabindex="-1">Goodnight <a class="header-anchor" href="#goodnight" aria-label="Permalink to &quot;Goodnight&quot;">​</a></h1><p>Say &quot;goodnight&quot; (or &quot;I&#39;m going to bed&quot;) and Frog Hub says goodnight back. Once it has finished speaking, it:</p><ul><li>turns the room&#39;s lights off, or dims them, or leaves them be;</li><li>keeps the screen dimmed and quiet until night mode ends in the morning (or until someone talks to it again);</li><li>plays a sleep sound, rain, waves or white noise, which fades out over its last minute.</li></ul><p>Ask for a bedtime story first and you&#39;ll get a short, gentle one. &quot;Goodnight, can I have the sea sounds for an hour?&quot; picks the sound and the time for that night only.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Each display has its own, under <strong>Settings → Goodnight</strong>: what happens to the lights (and how dim), which sound and for how long. <strong>▶ Hear it</strong> plays a few seconds of the sound. Night mode&#39;s hours, in the same Settings, decide when the morning is.</p><p>The sleep sounds are made on the tablet itself, so they need no internet and never run out partway through.</p><p>The lights need the grown-ups&#39; &quot;See and control the room&#39;s devices&quot; switch and the sound their &quot;Play music&quot; one; with either off, the rest still happens.</p><h2 id="every-night-at-the-same-time" tabindex="-1">Every night at the same time <a class="header-anchor" href="#every-night-at-the-same-time" aria-label="Permalink to &quot;Every night at the same time&quot;">​</a></h2><p>A <a href="/features/announcements#scheduled-jobs">scheduled job</a> can do it: &quot;every school night at half past seven, say goodnight on the bedroom display&quot;. Or from the server, say from a Home Assistant automation:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8790/local/announce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;goodnight&quot;: true, &quot;to&quot;: &quot;Bedroom&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8790/local/announce</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;goodnight&quot;: true, &quot;to&quot;: &quot;Bedroom&quot;, &quot;sound&quot;: &quot;waves&quot;, &quot;minutes&quot;: 30, &quot;say&quot;: &quot;Bedtime!&quot;}&#39;</span></span></code></pre></div><p><code>sound</code> is <code>rain</code>, <code>waves</code>, <code>white noise</code> or <code>none</code>, and <code>minutes</code> is between 5 and 180; leave them out for the display&#39;s own settings.</p><h2 id="night-mode" tabindex="-1">Night mode <a class="header-anchor" href="#night-mode" aria-label="Permalink to &quot;Night mode&quot;">​</a></h2><p>Every night, between the hours set in <strong>Settings → Night mode</strong> (9pm to 7am to begin with; every display shares them), the screen dims and the frog looks sleepy. Announcements and audio are only shown, not said or played, unless they&#39;re sent with <code>at_night</code>. Alarms still ring.</p>`,14)])])}const c=e(i,[["render",n]]);export{p as __pageData,c as default};
